    connect (p, p.permanent, G_OBJECT (tree), "set-image", G_CALLBACK (image_changed));
    connect (p, p.permanent, G_OBJECT (tree), "set-image", G_CALLBACK (image_changed_after), G_CONNECT_AFTER);
    result = true;
  });
