static GtkWidget *
gimp_int_radio_group_new_valist (gboolean       in_frame,
                                 const gchar   *frame_title,
                                 GCallback      radio_button_callback,
                                 gpointer       radio_button_callback_data,
                                 GDestroyNotify radio_button_callback_destroy,
                                 GtkOrientation orientation,
                                 gint           initial,
                                 va_list        args)
{
  GtkWidget *vbox;
  GtkWidget *button;
  GSList    *group;

  /*  radio button variables  */
  const gchar *label;
  gint         item_data;
  gpointer     item_ptr;
  GtkWidget  **widget_ptr;

  vbox = gtk_box_new (orientation, 2);

  group = NULL;

  if (radio_button_callback_destroy)
    g_object_weak_ref (G_OBJECT (vbox),
                       (GWeakNotify) radio_button_callback_destroy,
                       radio_button_callback_data);

  /*  create the radio buttons  */
  label = va_arg (args, const gchar *);

  while (label)
    {
      item_data  = va_arg (args, gint);
      widget_ptr = va_arg (args, GtkWidget **);

      item_ptr = GINT_TO_POINTER (item_data);

      if (label != GINT_TO_POINTER (1))
        button = gtk_radio_button_new_with_mnemonic (group, label);
      else
        button = gtk_radio_button_new (group);

      group = gtk_radio_button_get_group (GTK_RADIO_BUTTON (button));
      gtk_box_pack_start (GTK_BOX (vbox), button, FALSE, FALSE, 0);

      if (item_data)
        {
          g_object_set_data (G_OBJECT (button), "gimp-item-data", item_ptr);

          /*  backward compatibility  */
          g_object_set_data (G_OBJECT (button), "user_data", item_ptr);
        }

      if (widget_ptr)
        *widget_ptr = button;

      if (initial == item_data)
        gtk_toggle_button_set_active (GTK_TOGGLE_BUTTON (button), TRUE);

      g_signal_connect (button, "toggled",
                        radio_button_callback,
                        radio_button_callback_data);

      gtk_widget_show (button);

      label = va_arg (args, const gchar *);
    }

  if (in_frame)
    {
      GtkWidget *frame;

      frame = gimp_frame_new (frame_title);
      gtk_container_add (GTK_CONTAINER (frame), vbox);
      gtk_widget_show (vbox);

      return frame;
    }

  return vbox;
}

gimp_int_radio_group_new (gboolean       in_frame,
                          const gchar   *frame_title,
                          GCallback      radio_button_callback,
                          gpointer       radio_button_callback_data,
                          GDestroyNotify radio_button_callback_destroy,
                          gint           initial,
                          ...)
{
  GtkWidget *result;
  va_list    args;

  va_start (args, initial);
  result = gimp_int_radio_group_new_valist (in_frame, frame_title,
                                            radio_button_callback,
                                            radio_button_callback_data,
                                            radio_button_callback_destroy,
                                            GTK_ORIENTATION_VERTICAL,
                                            initial, args);
  va_end (args);

  return result;
}

/**
 * gimp_int_radio_group_new_with_orientation: (skip)
 *
 * GIMP-Painter compatibility entry point with the original varargs ABI.
 * Callback data is borrowed. As in the original switch, unknown orientation
 * values fall back to vertical.
 */
GtkWidget *
gimp_int_radio_group_new_with_orientation (gboolean       in_frame,
                                           const gchar   *frame_title,
                                           GCallback      radio_button_callback,
                                           gpointer       radio_button_callback_data,
